@@ -0,0 +1,35 @@
+// API keys and roles. A key is { key, name, role }; roles are in ROLES.
+import { AppError } from "../errors.js";
+
+/** The roles, weakest first. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+// Non-GET routes a cook may use (route patterns as registered in src/http/routes/).
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+// GET routes only managers may read.
+const MANAGER_READS = new Set(["GET /audit"]);
+
+/** Finds the API key sent as `Authorization: Bearer <key>`, or throws `unauthorized`. */
+export function authenticate(store, headers = {}) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const match = /^Bearer\s+(\S+)$/i.exec(String(name ? headers[name] : ""));
+  const found = match && (store.data.apiKeys ?? []).find((k) => k.key === match[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless the key's role may call `method` on the route `pattern`. */
+export function authorize(key, method, pattern) {
+  const route = `${method} ${pattern}`;
+  const ok =
+    key.role === "manager" ||
+    (key.role === "cook" && COOK_ROUTES.has(route)) ||
+    (method === "GET" && !MANAGER_READS.has(route) && ROLES.includes(key.role));
+  if (!ok) throw new AppError("forbidden", { role: key.role });
+}
